  renderCount += 1;                                 // 💥 side-effect trong render

  const discount = Math.random() > 0.5 ? 0.2 : 0;   // 💥 non-deterministic
  const snapshotAt = Date.now();                    // 💥 đổi theo từng lần chạy

  return (
