// ✅ Render = hàm thuần: cùng input → cùng output, không side-effect
function PriceTicker({ product }: { product: Product }) {
  // ✅ Derive từ props — deterministic, compiler memo an toàn
  const discount = product.discountPercent / 100;

  // ✅ Cần mốc thời gian? Ghi trong effect, không phải giữa render
  const [snapshotAt, setSnapshotAt] = useState<Date | null>(null);
  useEffect(() => {
    setSnapshotAt(new Date());
  }, [product.id]);

  // ✅ Cần đo lường? Cho vào handler — nơi side-effect được phép sống
  const handleBuy = () => {
    analytics.track('buy_click', { productId: product.id, ts: Date.now() });
  };

  return (
    <div>
      <span>-{discount * 100}%</span>
      {snapshotAt && <time>{snapshotAt.toLocaleTimeString()}</time>}
      <button onClick={handleBuy}>Mua ngay</button>
    </div>
  );
}

