function SearchResults({ items }: { items: Item[] }) {
  const renderCount = useRef(0);
  renderCount.current += 1; // 💥 mutation giữa chừng render — KHÔNG re-render

  // 💥 .sort() IN-PLACE đột biến thẳng mảng props của parent!
  const sorted = items.sort((a, b) => b.score - a.score);

