// ✅ Nguyên tắc: render chỉ ĐỌC — mọi ghi nằm ở handler/effect
function SearchResults({ items }: { items: Item[] }) {
  // ✅ Copy-on-write: mảng props của cha không bao giờ bị đột biến
  const sorted = [...items].sort((a, b) => b.score - a.score);

  // ✅ Số liệu hiển thị lên UI phải là STATE — ref không kích hoạt re-render
  const [renderCount, setRenderCount] = useState(0);
  useEffect(() => { setRenderCount((c) => c + 1); }, []); // ghi trong effect, không trong render

  return (
    <ul>
      <li aria-hidden>renders: {renderCount}</li>
      {sorted.map((it) => (
        <ItemRow key={it.id} item={it} />
      ))}
    </ul>
  );
}

// ✅ Pattern 'giá trị lần trước': ref chỉ được ghi trong useEffect
function usePrevious<T>(value: T) {
  const ref = useRef<T>();
  useEffect(() => void (ref.current = value), [value]);
  return ref.current;
}

